{"command": "python3 -c "
from PIL import Image, ImageFilter
import numpy as np
im=Image.open('radiograph.jpg').convert('L')
sm=np.asarray(im.filter(ImageFilter.GaussianBlur(12))).astype(np.float32)
H,W=sm.shape
# simple non-max suppression on dark
cells=[]
for y in range(30,H-30,20):
    for x in range(30,W-30,20):
        cells.append((sm[y,x],x,y))
cells.sort()
picked=[]
for v,x,y in cells:
    if all((x-px)**2+(y-py)**2>120**2 for _,px,py in picked):
        picked.append((v,x,y))
    if len(picked)>=20: break
for v,x,y in picked:
    print(x,y,round(float(v),1), 'frac', round(x/W,3), round(y/H,3))
"", "description": "Dark blob detection without scipy"}
